package com.asmj.marketplace.advertising;
import java.time.Instant; import java.time.LocalDate; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document("advertisement_events") public class AdEvent { @Id private String id; @Indexed private String campaignId; @Indexed private String eventType; @Indexed private String visitorKey; @Indexed private LocalDate eventDate; private Instant createdAt=Instant.now(); public String getId(){return id;} public void setId(String v){id=v;} public String getCampaignId(){return campaignId;} public void setCampaignId(String v){campaignId=v;} public String getEventType(){return eventType;} public void setEventType(String v){eventType=v;} public String getVisitorKey(){return visitorKey;} public void setVisitorKey(String v){visitorKey=v;} public LocalDate getEventDate(){return eventDate;} public void setEventDate(LocalDate v){eventDate=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
